package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	var n, s int
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	if scanner.Scan() {
		fmt.Sscanf(scanner.Text(), "%d", &n)
	}
	if scanner.Scan() {
		fmt.Sscanf(scanner.Text(), "%d", &s)
	}
	ans := (s + n - 1) / n
	fmt.Println(ans)
}

package main

import (
	"fmt"
)

func main() {
	var n, s int
	fmt.Scan(&n, &s)
	ans := s / n
	if s%n != 0 {
		ans++
	}
	fmt.Println(ans)
}

